#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
int main(){
    long long n,x,pos;
    cin>>n>>x>>pos;
    long long left=0,right=n;
    long long cl=0,cg=0;
    while(left<right){
        long long mid=(left+right)/2;
        if(mid==pos){ left=mid+1; continue;}
        if(mid<pos){ cl++; left=mid+1;}
        else { cg++; right=mid;}
    }
    long long avLess=x-1, avGreater=n-x;
    if(cl>avLess||cg>avGreater){cout<<0<<endl;return 0;}
    long long res=1;
    for(long long i=0;i<cl;i++) res=res*((avLess-i)%MOD)%MOD;
    for(long long i=0;i<cg;i++) res=res*((avGreater-i)%MOD)%MOD;
    long long rem=n-1-cl-cg;
    for(long long i=1;i<=rem;i++) res=res*(i%MOD)%MOD;
    cout<<res<<endl;
    return 0;
}
